// Deterministic policy check - the model never decides whether it is allowed to act.
const cfg = $('Config').first().json;
const b = $('Webhook').first().json.body || {};
const allowed = cfg.allowed_actions.split(',').map(s => s.trim());
const amount = Number(b.amount);
const reasons = [];
if (!b.request_id) reasons.push('missing request_id');
if (!allowed.includes(b.action)) reasons.push('action not allowed');
if (!(amount > 0)) reasons.push('amount must be positive');
if (amount > cfg.hard_cap_usd) reasons.push('amount exceeds hard cap');
let decision = 'needs_approval';
if (reasons.length) decision = 'invalid';
else if (amount <= cfg.auto_approve_limit_usd) decision = 'auto';
return [{ json: {
  request_id: String(b.request_id || 'unknown').slice(0, 64),
  action: String(b.action || '').slice(0, 64),
  account_id: String(b.account_id || '').slice(0, 32),
  amount,
  requested_by: String(b.requested_by || 'unknown').slice(0, 64),
  reason: String(b.reason || '').slice(0, 300),
  decision, reasons
} }];

