// Normalise the approver's response. No body = the wait timed out.
const req = $('Policy Check').first().json;
const body = $input.first().json.body;
let decision = 'timed_out';
if (body && body.decision === 'approve') decision = 'approved';
else if (body && body.decision === 'reject') decision = 'rejected';
return [{ json: { ...req, decision, decided_by: body ? String(body.approver || 'unknown').slice(0, 64) : 'system', notes: body ? String(body.notes || '').slice(0, 300) : 'no response within time limit' } }];
